import re

def string_expansion(s: str) -> str:
    if not s:
        return ''

    result = []
    current_multiplier = None

    i = 0
    while i < len(s):
        char = s[i]

        if char.isdigit():
            if current_multiplier is None:
                current_multiplier = int(char)
            else:
                current_multiplier = current_multiplier * 10 + int(char)
        elif char.isalpha():
            if current_multiplier is not None:
                result.append(char * current_multiplier)
                current_multiplier = None
            else:
                result.append(char)
        i += 1

    return ''.join(result)
